"""`.Gag pick`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Gag pick'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Color', 'NodeSocketColor')
    t.socket('OUTPUT', 'Alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Choice', 'NodeSocketFloat')
    t.socket('INPUT', 'Index', 'NodeSocketFloat', default_value=1.0)
    t.socket('INPUT', 'Color', 'NodeSocketColor')
    t.socket('INPUT', 'Alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Previous color', 'NodeSocketColor', default_value=(1.0, 1.0, 1.0, 1.0))
    t.socket('INPUT', 'Previous alpha', 'NodeSocketFloat')

    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-1200.0, 0.0),
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (900.0, 0.0),
    })
    t.node('ShaderNodeMath', 'Math', props={
        'location': (-600.0, 200.0),
        'operation': 'COMPARE',
    })
    t.node('ShaderNodeMix', 'Mix', props={
        'location': (-200.0, 200.0),
        'data_type': 'RGBA',
    })
    t.node('ShaderNodeMix', 'Mix.001', props={
        'location': (-200.0, -100.0),
    })

    t.link('Group Input', 'Choice', 'Math', 'Value')
    t.link('Group Input', 'Index', 'Math', 'Value_001')
    t.link('Math', 'Value', 'Mix', 'Factor_Float')
    t.link('Group Input', 'Previous color', 'Mix', 'A_Color')
    t.link('Group Input', 'Color', 'Mix', 'B_Color')
    t.link('Mix', 'Result_Color', 'Group Output', 'Color')
    t.link('Math', 'Value', 'Mix.001', 'Factor_Float')
    t.link('Group Input', 'Previous alpha', 'Mix.001', 'A_Float')
    t.link('Group Input', 'Alpha', 'Mix.001', 'B_Float')
    t.link('Mix.001', 'Result_Float', 'Group Output', 'Alpha')
    return t
